// Keep the studio services; implement only the game the user requested.
import { installStudio, makeRng } from './studio.js';
let rng;
installStudio({
  scene, renderer, camera, canvas: renderer.domElement,
  reset(seed) { rng = makeRng(seed); resetWorld(rng); },
  update(dt, ctx) { updateWorld(dt, ctx, rng); },
  render() { renderer.render(scene, camera); },
  probes() { return readActualGameState(); },
  cameras,
  // Add player() only when this game has a player; return its actual pose.
});
// resetWorld, updateWorld, readActualGameState and cameras belong to the requested game.
// No demo player, collectibles, score, terrain, or HUD is supplied by the harness.
